'use strict';
const careState={method:3,conditions:new Set(),selected:new Set()};
const careText=()=>CARE_I18N[language];
function careInherited(p){const out=new Set();if(!p)return out;if(p.history==='0'||p.motion==='0')out.add('nausea');const pairs={2:'heart',3:'breathing',4:'kidney',5:'liver',6:'breathing'};p.diseases.forEach(i=>{if(pairs[i])out.add(pairs[i])});return out;}
function careAssessment(p,state){
 const conditions=new Set([...state.conditions,...careInherited(p)]);
 const related={airway:['airway','breathing'],warming:['cold'],depth:['awareness'],block:['limb'],oxygen:['breathing','airway'],paracetamol:['pain'],dynastat:['pain'],naldebain:['pain'],ondansetron:['nausea']};
 const cautions={airway:[],warming:[],depth:[],block:['bleeding','allergy'],oxygen:[],paracetamol:['liver','kidney','allergy','pregnancy'],dynastat:['liver','kidney','heart','breathing','ulcer','allergy','bleeding','pregnancy'],naldebain:['breathing','liver','kidney','allergy','pregnancy','opioids'],ondansetron:['rhythm','heart','liver','allergy','pregnancy']};
 return CARE_IDS.map(id=>({id,matches:related[id].filter(c=>conditions.has(c)),flags:cautions[id].filter(c=>conditions.has(c)),child:!!p&&Number(p.age)<18,review:['airway','block','oxygen','paracetamol','dynastat','naldebain','ondansetron'].includes(id)}));
}
function careItemInfo(id){return careText().items[CARE_IDS.indexOf(id)]}
function cardForItem(result){const c=careText(),index=CARE_IDS.indexOf(result.id),info=c.items[index],caution=result.flags.length||result.child;const card=document.createElement('article');card.className='care-item'+(caution?' needs-review':'');card.dataset.item=result.id;
 const head=document.createElement('div');head.className='care-item-head';head.append(textElement('span',String(index+1).padStart(2,'0'),'care-item-number'),textElement('h4',info[0]));card.append(head,textElement('span',caution||result.review?c.review:result.matches.length?c.match:c.general,'care-badge'),textElement('p',info[1]));
 if(result.matches.length)card.append(textElement('p',c.reason+result.matches.map(key=>c.conditionLabels[CONDITION_IDS.indexOf(key)]).join(' · '),'care-reason'));
 if(caution)card.append(textElement('p',result.child?c.childReview:c.healthReview,'care-warning'));
 const label=document.createElement('label');label.className='care-choice';const box=document.createElement('input');box.type='checkbox';box.value=result.id;box.checked=careState.selected.has(result.id);box.onchange=()=>{if(box.checked)careState.selected.add(result.id);else careState.selected.delete(result.id);document.querySelectorAll(`input[data-care-id="${result.id}"]`).forEach(other=>other.checked=box.checked);updateCareSummary()};box.dataset.careId=result.id;label.append(box,textElement('span',c.discuss+' · '+info[0]));card.append(label);return card;}
function updateCareSummary(){const el=$('#care-selection-summary');if(el){el.textContent=careText().selectedCount.replace('{n}',careState.selected.size);const list=$('#care-selected-list');list.textContent=careState.selected.size?[...careState.selected].map(id=>careItemInfo(id)[0]).join(' · '):careText().notChosen;}}
function renderCareChoices(){const c=careText(),suggested=$('#care-suggestions'),all=$('#care-all-items');const results=careAssessment(patient,careState);suggested.innerHTML='';all.innerHTML='';const matched=results.filter(r=>r.matches.length||r.id==='warming');if(!matched.length)suggested.append(textElement('p',c.noMatches,'hint'));matched.forEach(r=>suggested.append(cardForItem(r)));results.forEach(r=>all.append(cardForItem(r)));updateCareSummary();}
function renderPreopCare(root){const c=careText();const section=document.createElement('section');section.className='preop-care';section.innerHTML=`<div class="visitor-banner"><svg viewBox="0 0 100 100" aria-hidden="true">${staffAvatar(50,47,'#93b8a4',false)}</svg><div><h3>${esc(c.visitorTitle)}</h3><p>${esc(c.visitorBody)}</p></div></div><h3>${esc(c.section)}</h3><p>${esc(c.intro)}</p><fieldset class="care-methods"><legend>${esc(c.method)}</legend>${c.methods.map((name,i)=>`<label><input type="radio" name="care-method" value="${i}" ${careState.method===i?'checked':''}>${esc(name)}</label>`).join('')}</fieldset><fieldset class="care-conditions"><legend>${esc(c.conditions)}</legend><div class="condition-grid"></div></fieldset><h3>${esc(c.suggestions)}</h3><div class="care-grid" id="care-suggestions" aria-live="polite"></div><details class="care-all"><summary>${esc(c.allItems)}</summary><div class="care-grid" id="care-all-items"></div></details><div class="care-summary"><h4 id="care-selection-summary"></h4><p id="care-selected-list"></p><p class="hint">${esc(c.costs)}</p><button class="primary" id="save-care">${esc(c.save)}</button><p class="hint">${esc(c.notice)}</p></div>`;
 root.append(section);section.append(careSources());const inherited=careInherited(patient);CONDITION_IDS.forEach((id,i)=>{const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=id;box.name='care-condition';box.checked=careState.conditions.has(id)||inherited.has(id);box.disabled=inherited.has(id);box.onchange=()=>{if(box.checked)careState.conditions.add(id);else careState.conditions.delete(id);renderCareChoices()};label.append(box,textElement('span',c.conditionLabels[i]));if(inherited.has(id)){const labels={'zh-Hant':'由基本資料帶入',en:'From your profile',id:'Dari data diri',th:'จากข้อมูลของคุณ',vi:'Từ thông tin cá nhân',fil:'Mula sa iyong impormasyon'};label.append(textElement('small',labels[language]))}section.querySelector('.condition-grid').append(label)});
 section.querySelectorAll('[name=care-method]').forEach(box=>box.onchange=()=>{careState.method=Number(box.value);renderCareChoices()});$('#save-care').onclick=()=>$('#topic-dialog').close();renderCareChoices();
}
function staffAvatar(x,y,color,surgeon){return `<g transform="translate(${x} ${y})"><path d="M-24 48V9Q0-4 24 9V48Z" fill="${color}"/><path d="M-17 48V27m34 21V27" stroke="#385f5d" stroke-width="3"/><circle cy="-9" r="19" fill="#efc7a7"/><path d="M-20-13q0-27 20-23 23-1 20 24Z" fill="${surgeon?'#779f9b':'#b4cec0'}"/><path d="M-18-16H18" stroke="#547c75" stroke-width="2"/><circle cx="-7" cy="-12" r="1.6" fill="#294a45"/><circle cx="7" cy="-12" r="1.6" fill="#294a45"/><path d="M-14-6h28v12q-14 9-28 0Z" fill="#edf7f2" stroke="#98b8ab"/><path d="M-10 0H10M-8 4H8" stroke="#afcfc0"/><path d="M-24 14l-10 24m58-24l10 24" stroke="${color}" stroke-width="12" stroke-linecap="round"/>${surgeon?'':'<path d="M-10 11v13q10 14 20 0V11" fill="none" stroke="#426d68" stroke-width="3"/><circle cx="10" cy="26" r="4" fill="#dfe9e2" stroke="#426d68"/>'}</g>`;}
function medicineIcon(id){const color={paracetamol:'#79a99d',dynastat:'#bc946d',naldebain:'#9b8db6',ondansetron:'#7d9fb8'}[id];return `<svg viewBox="0 0 100 100" aria-hidden="true"><ellipse cx="50" cy="88" rx="28" ry="6" fill="#315c4715"/><rect x="34" y="12" width="32" height="13" rx="3" fill="${color}"/><rect x="30" y="23" width="40" height="61" rx="9" fill="#f6fcf8" stroke="${color}" stroke-width="3"/><path d="M34 56h32v19q0 5-5 5H39q-5 0-5-5Z" fill="${color}" opacity=".24"/><rect x="32" y="38" width="36" height="27" rx="3" fill="${color}"/><path d="M43 51h14m-7-7v14" stroke="#fff" stroke-width="3"/></svg>`;}

