function renderOperatingRoom(root){const c=careText(),meds=['paracetamol','dynastat','naldebain','ondansetron'].filter(id=>careState.selected.has(id));root.innerHTML=`<div class="operating-room-v2"><div class="station-chip">${esc(t('station',{n:3}))}</div><h2 id="topic-title">${esc(c.sceneTitle)}</h2><div class="team-ribbon">${c.staff.map((name,i)=>`<div class="team-card" data-staff="${['anesthesiologist','anesthesia-nurse','surgery-team'][i]}"><svg viewBox="0 0 100 110" aria-hidden="true">${staffAvatar(50,51,['#7fa89b','#a6c4ad','#7aa8a1'][i],i===2)}</svg><strong>${esc(name)}</strong></div>`).join('')}</div><p class="hint room-disclaimer">${esc(c.sceneIntro)}</p>
<div class="scene-stage ${meds.length?'has-medicines':''}"><div class="room-illustration">${sceneSVG()}</div>${meds.length?`<aside class="scene-med-rail"><h3>${esc(c.medTitle)}</h3><div class="medicine-grid"></div><p class="hint">${esc(c.medNote)}</p></aside>`:''}</div>
<div class="room-info-panels"><section class="monitor-panel"><h3>${esc(c.basic)}</h3><ol class="monitor-key">${[c.labels[0],c.labels[1],c.labels[2],c.labels[3]].map((label,i)=>`<li><b>${i+1}</b><span>${esc(label)}${i===1?`<small>${esc(c.bp)}</small>`:''}</span></li>`).join('')}</ol><p class="hint">${esc(c.bpNote)}</p>${!careState.selected.has('oxygen')?`<p class="hint">${esc(c.preoxygenationNote)}</p>`:''}</section><section class="choices-panel"><h3>${esc(c.optional)}</h3><p class="hint">${esc(c.method)}: ${esc(c.methods[careState.method])}</p><section class="warming-status"><h3>${esc(c.warmTitle)}</h3><p class="hint" id="warming-status-text">${esc(careState.selected.has('warming')?c.warmShown:c.warmHidden)}</p><label><input id="room-warming-toggle" type="checkbox" ${careState.selected.has('warming')?'checked':''}><span>${esc(c.warmToggle)}</span></label></section><div class="selected-scene-list">${careState.selected.size?[...careState.selected].map(id=>`<span data-scene-item="${id}">✓ ${esc(careItemInfo(id)[0])}</span>`).join(''):`<p class="hint">${esc(c.notChosen)}</p>`}</div><button id="scene-edit" class="secondary">${esc(c.edit)}</button></section></div><button class="primary" id="scene-back">${esc(t('backMap'))}</button></div>`;
$('#room-warming-toggle').onchange=e=>{const scroll=$('#topic-dialog').scrollTop;if(e.target.checked)careState.selected.add('warming');else careState.selected.delete('warming');renderOperatingRoom(root);$('#topic-dialog').scrollTop=scroll;$('#room-warming-toggle').focus({preventScroll:true})};meds.forEach(id=>{const card=document.createElement('article');card.className='medicine-card';card.dataset.medicine=id;card.innerHTML=medicineIcon(id);card.append(textElement('strong',careItemInfo(id)[0]));card.title=careItemInfo(id)[1];root.querySelector('.medicine-grid').append(card)});root.append(careSources());$('#scene-back').onclick=()=>$('#topic-dialog').close();$('#scene-edit').onclick=()=>{$('#topic-dialog').close();visit(0)};}

function careSources(){const details=document.createElement('details');details.className='care-sources';details.append(textElement('summary',careText().sources));const sources=[['Preoxygenation · DAS','https://pmc.ncbi.nlm.nih.gov/articles/PMC4650961/'],['ASA · Monitoring','https://www.asahq.org/standards-and-practice-parameters/standards-for-basic-anesthetic-monitoring'],['Paracetamol / Acetaminophen · DailyMed','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=464e404a-1957-44a2-a53a-f2a9d3c15bde'],['Dynastat · Medsafe','https://www.medsafe.govt.nz/profs/datasheet/d/Dynastatinj.pdf'],['Naldebain · Product information','https://www.tai-an.com.tw/upload/DrugInfo/Drug/Instructions/INAB.pdf'],['Ondansetron · MedlinePlus','https://medlineplus.gov/druginfo/meds/a606022.html']];sources.forEach(([name,url])=>{const a=textElement('a',name+' ↗');a.href=url;a.target='_blank';a.rel='noopener';details.append(a)});return details;}


